css:
.header {
    display: flex;
    display: -webkit-box;
    justify-content: justify;
    -webkit-box-pack: justify;
    border-bottom: 1px solid #dddddd;
    padding-bottom: 4px;
}

.invoice-container {
  font-family: Arial, sans-serif;
  color: #333;

  margin: auto;
  box-sizing: border-box;
}


.patient-info,
.invoice-details {
  margin-bottom: 20px;
}

h3 {
  border-bottom: 2px solid #333;
  padding-bottom: 5px;
  margin-bottom: 10px;
}

.invoice-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 20px;
}

.invoice-table th,
.invoice-table td {
  border: 1px solid #ddd;
  padding: 4px 6px;         
  text-align: left;
  font-size: 12px;
  line-height: 1.2;         
}

.invoice-table th {
  background-color: #f5f5f5;
}

.total-section {
  text-align: right;
  font-size: 16px;
  font-weight: bold;
}

.note-section {
  margin-top: 20px;
  text-align: center;
  font-style: italic;
}

.grayscale { filter: grayscale(100%); }


  .page-number:before {
    content: counter(page);
  }
  .total-pages:before {
    content: counter(pages);
  }

  @media screen {
    #footer-html {
      display: none;
    }
  }

html:
{% set company = frappe.db.get_value("Company", doc.company, ["*"], as_dict = true) %}
{% set letter_head = frappe.db.get_value("Letter Head", company.default_letter_head, ["image"], as_dict=true) %}
{% set links = frappe.get_all('Dynamic Link', filters={'link_doctype': 'Company', 'link_name': doc.company, 'parenttype': 'Address'}, fields=['parent']) %}
{% if links %}
{% set address = frappe.db.get_value("Address", links[0].parent, ["*"], as_dict=true) %}
{% set patient = frappe.db.get_value("Patient", doc.patient, ["*"], as_dict=true) %}
{% set inpatient = frappe.db.get_value("Inpatient Record", doc.inpatient_record, ["*"], as_dict=true) %}
{% set dob = frappe.utils.getdate(patient.dob) %} {# Replace with actual DOB #}
{% set today = frappe.utils.nowdate() %}
{% set birth_date = frappe.utils.getdate(dob) %}
{% set current_date = frappe.utils.getdate(today) %}
{% set age = current_date.year - birth_date.year - ((current_date.month, current_date.day) < (birth_date.month, birth_date.day)) %}
{% set admission = frappe.utils.getdate(inpatient.admitted_datetime) %}
{% set discharge = frappe.utils.getdate(inpatient.discharge_datetime) %}
{% endif %}

{% macro display_items(items)%}
<table class="invoice-table">
    <thead>
      <tr>
        <th>Item</th>
        <th>Qty</th>
        <th>Rate</th>
        <th>Amount</th>
      </tr>
    </thead>
    <tbody>
      {% for item in items %}
      <tr>
        <td>{{ item.item_name }}</td>
        <td style="width: 60px;">{{ item.qty }}</td>
        <td style="width: 120px;">{{ frappe.utils.fmt_money(item.rate, currency=doc.currency) }}</td>
        <td style="width: 120px;">{{ frappe.utils.fmt_money(item.amount, currency=doc.currency) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
{% endmacro%}
<div class="invoice-container">
    <div class="header">
        <div class="">
            <img src="{{letter_head.image}}"  style="width:100px; margin-bottom:32px;" class="grayscale"/>
        </div>
        <div style="text-align: center">
            <h1>Premium Care Clinic</h1>
            <h2>VAT Invoice</h2>
        </div>
        <div style="text-align: right;">
            {% if address.address_title %}
                <p style="font-weight: bold; font-size: large;">{{address.address_title}}<p/>
            {% endif %}
            {% if address.address_line1 %}
                <p>{{address.address_line1}}</p>
            {% endif %}
            {% if address.city %}
                <p>{{address.city}}</p>
            {% endif %}
            {% if address.pincode %}
                <p>{{address.pincode}}</p>
            {% endif %}
            <p>Tel: 4908128</p>
            <p>BRN: C22188669</p>
            <p>Email: info@premiumcareclinic.mu</p>
        </div>

    </div>

  <section class="patient-info">
    <h3>Patient Information</h3>
    <p><strong>Name:</strong> {{ doc.patient_name }}</p>
    <p><strong>Patient ID:</strong> {{ doc.patient }}</p>
    <p><strong>Tel:</strong> {{ patient.mobile }}</p>
    <p><strong>D.O.B:</strong> {{ frappe.utils.formatdate(patient.dob, "dd/MM/yyyy") }}  ({{age}}) years old</p>
  </section>

  <section class="invoice-details">
    <h3>Invoice Details</h3>
    <p><strong>Invoice No:</strong> {{ doc.name }}</p>
    <p><strong>Date:</strong> {{ frappe.utils.formatdate(doc.posting_date, "dd/MM/yyyy") }}</p>
    <p><strong>Date of Admission:</strong> {{ frappe.utils.formatdate(admission, "dd/MM/yyyy") }}</p>
    <p><strong>Date of Discharge:</strong> {{ frappe.utils.formatdate(discharge, "dd/MM/yyyy") }}</p>
  </section>

  {% set imaging_groups = ["CT Scan", "XRAY", "MRI", "RADIOLOGY", "USS", "Other RAD"] %}
    {% set services_groups = ["CATH LAB", "CARDIAC UNIT", "PROCEDURES", "ROOMS/ DAYWARD", "Services"] %}
    {% set consumables_groups = ["CONSUMABLES", "PHARMA CONSUMABLE", "CONSIGNMENT"] %}

    {% set imaging_items = [] %}
    {% set services_items = [] %}
    {% set consumables_items = [] %}
    {% set other_items = {} %}

    {% for item_group, items in doc.item_by_item_groups().items() %}
        {% if item_group in imaging_groups %}
            {% set _ = imaging_items.extend(items) %}
        {% elif item_group in services_groups %}
            {% set _ = services_items.extend(items) %}
        {% elif item_group in consumables_groups %}
            {% set _ = consumables_items.extend(items) %}
        {% else %}
            {% set _ = other_items.update({item_group: items}) %}
        {% endif %}
    {% endfor %}

    {% if imaging_items %}
        <h4>Imaging</h4>
        {{ display_items(imaging_items) }}
    {% endif %}

    {% if services_items %}
        <h4>Services</h4>
        {{ display_items(services_items) }}
    {% endif %}

    {% if consumables_items %}
        <h4>Consumables</h4>
        {{ display_items(consumables_items) }}
    {% endif %}

    {% for group, items in other_items.items() %}
        <h4>{{ group }}</h4>
        {{ display_items(items) }}
    {% endfor %}

  <footer>
    <div class="total-section">
      <p><strong>Net Total:</strong> {{ frappe.utils.fmt_money(doc.total, currency=doc.currency) }}</p>
        {% if doc.discount_amount < 0 %}
            <p><strong>Discount:</strong> {{ frappe.utils.fmt_money(doc.discount_amount, currency=doc.currency) }}</p>
        {% endif %}
        {% if doc.total_taxes_and_charges > 0 %}
            <p><strong>VAT:</strong> {{ frappe.utils.fmt_money(doc.total_taxes_and_charges, currency=doc.currency) }}</p>
        {% endif %}
        {% if doc.outstanding_amount > 0 %}
            {% set deposit = doc.net_total - doc.outstanding_amount%}
            {% if deposit > 0%}
                <p><strong>Deposit:</strong> {{ frappe.utils.fmt_money(deposit, currency=doc.currency) }}</p>
            {% endif %}
            {% set total = doc.outstanding_amount%}
        {% else %}
            {% set total = doc.net_total %}
        {% endif %}
      <p><strong>Total:</strong> {{ frappe.utils.fmt_money(total, currency=doc.currency) }}</p>
    </div>
    <div class="note-section">
      <p>Thank you for choosing our clinic. Wishing you a speedy recovery!</p>
    </div>
  </footer>

</div>

<div id="footer-html" style="display: none;">
  <div style="width: 100%; font-size: 10px; text-align: right; padding-right: 20px;">
    Page <span class="pageNumber"></span> of <span class="totalPages"></span>
  </div>
</div>
